const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false, staleTime: 15_000 } } });
const money = (value?: number) => value == null ? '—' : `$${Math.round(value / 1000)}k`;
const initials = (value = '') => value.split(/\s+/).filter(Boolean).slice(0, 2).map((word) => word[0]).join('').toUpperCase() || 'N';
const errorText = (error: unknown) => {
  if (error && typeof error === 'object' && 'message' in error) return String((error as { message: unknown }).message);
  return 'Something went wrong. Please try again.';
};
const bust = (client: ReturnType<typeof useQueryClient>, keys: readonly (readonly unknown[])[]) => keys.forEach((queryKey) => void client.invalidateQueries({ queryKey }));
function useNotify() {
  const [message, setMessage] = useState('');
  useEffect(() => {
    if (!message) return;
    const timer = window.setTimeout(() => setMessage(''), 4700);
    return () => window.clearTimeout(timer);
  }, [message]);
  return { message, notify: setMessage, view: message ? <div className="toast-error" role="alert" data-testid="status-toast">{message}</div> : null };
}
