function Eyebrow({ children }: { children: ReactNode }) { return <div className="eyebrow">{children}</div>; }
function Loading({ count = 3 }: { count?: number }) { return <div className="job-grid">{Array.from({ length: count }, (_, index) => <div className="skeleton" key={index} />)}</div>; }
function CountUp({ value }: { value: number }) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setCount(value);
      return;
    }
    let start: number | null = null;
    let frame = 0;
    const tick = (time: number) => {
      if (start === null) start = time;
      const progress = Math.min((time - start) / 650, 1);
      setCount(Math.round(value * (1 - Math.pow(1 - progress, 3))));
      if (progress < 1) frame = window.requestAnimationFrame(tick);
    };
    frame = window.requestAnimationFrame(tick);
    return () => window.cancelAnimationFrame(frame);
  }, [value]);
  return <>{count}</>;
}
function Problem({ error, retry }: { error: unknown; retry?: () => void }) {
  const message = errorText(error);
  const missingDb = /database|mongo|not configured|unavailable/i.test(message);
  return <div className="notice" role="alert" data-testid="status-api-error"><h3>{missingDb ? 'Marketplace data is not connected yet' : 'We couldn’t load this view'}</h3><p>{missingDb ? 'Add your MongoDB Atlas connection URI as the MONGODB_URI secret in Replit, then restart the API service. NEXORA will not save or show sample data until the database is available.' : message}</p>{retry && <button className="btn" onClick={retry} data-testid="button-retry">Try again <ArrowRight size={14} /></button>}</div>;
}
function Empty({ title, text, action, href }: { title: string; text: string; action?: string; href?: string }) {
  return <div className="empty-state"><div className="empty-icon"><Sparkles size={19} /></div><h3>{title}</h3><p>{text}</p>{action && href && <Link className="btn btn-primary" href={href} data-testid="link-empty-action">{action}<ArrowRight size={14} /></Link>}</div>;
}
function JobCard({ job, saved = false, onSave, compact = false }: { job: Job; saved?: boolean; onSave?: () => void; compact?: boolean }) {
  return <article className={compact ? 'job-row' : 'job-card'} data-testid={`card-job-${job.id}`}>
    <div className="company-monogram">{initials(job.companyName)}</div>
    <div className={compact ? 'row-content' : ''}>
      <Link className={compact ? 'row-title' : 'job-title'} href={`/jobs/${job.id}`} data-testid={`link-job-${job.id}`}>{job.title}</Link>
      <div className={compact ? 'row-company' : 'company-name'}>{job.companyName}</div>
      <div className="job-details"><span><MapPin size={13} />{job.location}</span><span><Briefcase size={13} />{job.jobType}</span><span><Clock3 size={13} />{job.experienceLevel}</span></div>
      {!compact && <div className="chips">{job.skills.slice(0, 3).map((skill) => <span className="chip" key={skill}>{skill}</span>)}</div>}
    </div>
    <div className={compact ? 'row-right' : 'job-bottom'}><span className="salary">{money(job.salaryMin)}–{money(job.salaryMax)}</span>{onSave && <button className={`btn icon-btn ${saved ? 'saved' : ''}`} onClick={onSave} aria-label={saved ? 'Remove saved job' : 'Save job'} data-testid={`button-save-job-${job.id}`}><Heart size={16} fill={saved ? 'currentColor' : 'none'} /></button>}<Link className="btn" href={`/jobs/${job.id}`} data-testid={`link-view-job-${job.id}`}>{compact ? 'View role' : 'Details'} <ArrowRight size={13} /></Link></div>
  </article>;
}
